CREATE TABLE IF NOT EXISTS supplies (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, unit VARCHAR(30) NOT NULL, stock BIGINT NOT NULL, minimum BIGINT NOT NULL, maximum BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, customer VARCHAR(120) NOT NULL, product VARCHAR(120) NOT NULL, quantity INT NOT NULL, due_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ABERTO');
CREATE TABLE IF NOT EXISTS requirements (order_id BIGINT NOT NULL, supply_id BIGINT NOT NULL, per_unit INT NOT NULL, PRIMARY KEY(order_id,supply_id), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(supply_id) REFERENCES supplies(id));
